449	// attachSandboxExec attaches to a plain (non-terminal) exec. A TTY exec
450	// reconnects on a dropped websocket exactly like a terminal attach does — the
451	// sandbox-agent's replay repaints the current screen, which is well-defined
452	// for a PTY. A non-TTY exec has no such buffer to replay (no byte-exact
453	// resumption of piped stdout), so it stays on the direct, fail-on-disconnect
454	// transport.
455	func (a *App) attachSandboxExec(ctx context.Context, projectID, sandboxID, execID string, interactive, tty bool, stdin io.Reader, stdout, stderr io.Writer) error {
456		conn, err := a.openExecAttachConn(ctx, projectID, sandboxID, execID, tty)
457		if err != nil {
458			return a.execAttachError(ctx, projectID, sandboxID, execID, err)
459		}
460		defer conn.Close()
461	
462		opts := client.Options{
463			Conn:     conn,
464			Stdin:    stdin,
465			Stdout:   stdout,
466			Stderr:   stderr,
467			Console:  client.NewOSConsole(stdin, stdout),
468			Kind:     "discobox exec",
469			Action:   "attach exec",
470			RawMode:  interactive && tty,
471			Terminal: tty,
472			CopyInput: func(ctx context.Context, s *client.Session) error {
473				return copySandboxExecInput(ctx, s, interactive)
474			},
475			InterruptNotice: interruptNotice(stderr, interactive && tty, "the discobox"),
476		}
477		if tty {
478			// SignalReady pairs with the replay this dial asked for: the remote must
479			// not stream replay history before the output reader is running. OtherErr
480			// keeps a transient close in the auxiliary goroutines (resize, signals,
481			// input) from ending the session while the resumable Conn is still
482			// reconnecting underneath them — only copyOutput's own read failure, via
483			// the Done callback, gets to decide the attach is really over.
484			opts.SignalReady = true
485			opts.OtherErr = func(err error) (bool, error) {
486				if client.IsDone(err) {
487					return true, nil
488				}
489				return false, err
490			}
491		}
492		session := client.New(opts)
493		if tty {
494			if err := session.WriteInitialResize(); err != nil {
495				return err
496			}
497		}
498		if _, err := a.startSandboxExec(ctx, projectID, sandboxID, execID); err != nil {
499			return err
500		}
501		if err := session.Run(ctx); err != nil {
502			if errors.Is(err, client.ErrInterrupted) {
503				return interruptedExit()
504			}
505			return err
506		}
507		return nil
508	}
509	
510	// openExecAttachConn opens the attach connection for a plain exec: the
511	// reconnecting, replay transport for a TTY, the direct one otherwise.
512	func (a *App) openExecAttachConn(ctx context.Context, projectID, sandboxID, execID string, tty bool) (execstream.Conn, error) {
513		if !tty {
514			return a.openSandboxExecAttach(ctx, projectID, sandboxID, execID, false)
515		}
516		return a.openReconnectingSandboxExecAttach(ctx, projectID, sandboxID, execID, execAttachOptions{replay: true})
517	}
518	
519	// attachRejectedError is an attach the sandbox-agent refused with an HTTP
520	// status. It carries the agent's own explanation, which for a terminal
521	// condition (an ended session, a missing exec) is more useful than anything the
522	// client can infer, so it is reported as-is.
523	type attachRejectedError struct {
524		status     int
525		statusText string
526		message    string
527	}
528	
529	func (e attachRejectedError) Error() string {
530		if e.message == "" {
531			return "attach exec: " + e.statusText
532		}
533		return "attach exec: " + e.message
534	}
535	
536	// explained reports whether the agent gave a definitive reason, so the client
537	// does not append its own guess at what went wrong.
538	func (e attachRejectedError) explained() bool {
539		return e.message != "" && (e.status == http.StatusConflict || e.status == http.StatusNotFound)
540	}
541	
542	// attachErrorMessage unwraps the agent's JSON error envelope, falling back to
543	// the raw body for a response that is not one.
544	func attachErrorMessage(body []byte) string {
545		var envelope struct {
546			Error string `json:"error"`
547		}
548		if err := json.Unmarshal(body, &envelope); err == nil && strings.TrimSpace(envelope.Error) != "" {
549			return strings.TrimSpace(envelope.Error)
550		}
551		return strings.TrimSpace(string(body))
552	}
553	
554	// execAttachError checks the authoritative exec record after an attach cannot
555	// be opened. A missing shim socket commonly means the command already exited;
556	// reporting only the transport error hides the command's actual result.
557	func (a *App) execAttachError(ctx context.Context, projectID, sandboxID, execID string, attachErr error) error {
558		var rejected attachRejectedError
559		if errors.As(attachErr, &rejected) && rejected.explained() {
560			return attachErr
561		}
562		exec, err := a.getSandboxExec(ctx, projectID, sandboxID, execID)
563		if err != nil {
564			return attachErr
565		}
566		switch exec.Status {
567		case apiclientgen.SandboxExecStatusExited, apiclientgen.SandboxExecStatusFailed, apiclientgen.SandboxExecStatusLost:
568			detail := fmt.Sprintf("exec %s is %s", exec.ID, exec.Status)
569			if code, ok := exec.ExitCode.Get(); ok {
570				detail += fmt.Sprintf(" with exit code %d", code)
571			}
572			if message := strings.TrimSpace(exec.Error.Or("")); message != "" {
573				detail += ": " + message
574			}
575			return fmt.Errorf("%w; %s", attachErr, detail)
576		default:
577			return attachErr
578		}
579	}
