581	func (a *App) openSandboxExecAttach(ctx context.Context, projectID, sandboxID, execID string, replay bool) (execstream.Conn, error) {
582		baseURL, httpClient, err := a.httpClient()
583		if err != nil {
584			return nil, err
585		}
586		u, err := url.Parse(strings.TrimRight(baseURL, "/"))
587		if err != nil {
588			return nil, err
589		}
590		switch u.Scheme {
591		case "http":
592			u.Scheme = "ws"
593		case "https":
594			u.Scheme = "wss"
595		default:
596			return nil, fmt.Errorf("attach exec: unsupported websocket base URL scheme %q", u.Scheme)
597		}
598		u.Path = strings.TrimRight(u.Path, "/") + "/api/projects/" + url.PathEscape(projectID) + "/sandboxes/" + url.PathEscape(sandboxID) + "/execs/" + url.PathEscape(execID) + "/attach"
599		if replay {
600			u.RawQuery = "replay=true"
601		}
602		conn, resp, err := websocket.Dial(ctx, u.String(), &websocket.DialOptions{
603			HTTPClient: httpClient,
604		})
605		if err != nil {
606			if resp != nil && resp.Body != nil {
607				defer resp.Body.Close()
608				body, _ := io.ReadAll(io.LimitReader(resp.Body, 64*1024))
609				return nil, attachRejectedError{status: resp.StatusCode, statusText: resp.Status, message: attachErrorMessage(body)}
610			}
611			return nil, fmt.Errorf("attach exec: %w", err)
612		}
613		netConn := websocket.NetConn(ctx, conn, websocket.MessageBinary)
614		frames := &websocketAttachFrames{
615			directAttachFrames: &directAttachFrames{conn: netConn},
616			socket:             conn,
617		}
618		go func() {
619			if err := pingAttachWebSocket(ctx, conn); err != nil {
620				// The server side is gone; close the conn so the attach session's
621				// blocked reads and writes unblock instead of hanging forever.
622				_ = netConn.Close()
623			}
624		}()
625		return frames, nil
626	}
