628	// execAttachOptions tunes a reconnecting attach.
629	type execAttachOptions struct {
630		// replay repaints the session's current screen on connect.
631		replay bool
632		// event receives transport lifecycle changes.
633		event func(resume.Event)
634		// timing receives transport heartbeat and positioned-action RTT samples from
635		// the shared resumable stream.
636		timing resume.TimingOptions
637		// notWorkingHere marks an attach to a discobox nobody's code is in — the
638		// throwaway sandbox a harness's configure flow runs in — so it does not
639		// push local commits into an origin the way every other terminal attach
640		// does (ADR 26-09-05-008 §1 on automatic push). It is the attach saying what it is
641		// for; nothing else about the attach differs.
642		notWorkingHere bool
643	}
