645	func (a *App) openReconnectingSandboxExecAttach(
646		ctx context.Context,
647		projectID, sandboxID, execID string,
648		opts execAttachOptions,
649	) (*resume.Conn, error) {
650		dial := func(ctx context.Context) (execstream.Conn, error) {
651			conn, err := a.openSandboxExecAttach(ctx, projectID, sandboxID, execID, opts.replay)
652			if err != nil {
653				return nil, err
654			}
655			return conn, nil
656		}
657		conn, err := dial(ctx)
658		if err != nil {
659			return nil, err
660		}
661		done := func(ctx context.Context) (bool, error) {
662			return a.sandboxExecAttachDone(ctx, projectID, sandboxID, execID)
663		}
664		return resume.New(ctx, conn, resume.Options{
665			Dial:   dial,
666			Done:   done,
667			Event:  opts.event,
668			Timing: opts.timing,
669		})
670	}
