672	// sandboxExecAttachDone decides whether a broken attach should reconnect or end.
673	// The question it answers is whether the command itself finished or the runtime
674	// disappeared underneath it: a recorded exit is the command's own result and
675	// ends the session, while a lost unit is an ungraceful disappearance that the
676	// attach can recover from.
677	func (a *App) sandboxExecAttachDone(ctx context.Context, projectID, sandboxID, execID string) (bool, error) {
678		exec, err := a.getSandboxExec(ctx, projectID, sandboxID, execID)
679		if err != nil {
680			// The exec read failed. A stopped or stopping sandbox took the terminal with
681			// it, so end the attach instead of reconnecting forever; we never start the
682			// sandbox back up here (a future `discobox attach` will own autostart). Any
683			// other failure does not prove the terminal ended — a transient control-plane
684			// blip — so keep retrying the websocket.
685			if done, stopErr := a.sandboxStoppedAttachDone(ctx, projectID, sandboxID); done {
686				return true, stopErr
687			}
688			return false, err
689		}
690		switch exec.Status {
691		case apiclientgen.SandboxExecStatusExited:
692			if code, ok := exec.ExitCode.Get(); ok && code != 0 {
693				return true, client.ExitError{Code: int(code)}
694			}
695			return true, nil
696		case apiclientgen.SandboxExecStatusLost:
697			// The unit vanished without the shim recording an exit — a killed or
698			// restarted container, not a command that ended. Reconnecting relaunches it,
699			// but only through the virtual primary id: a concrete exec id names one
700			// session, and nothing will ever revive it.
701			if execID == primaryExecID {
702				return false, nil
703			}
704			return true, execAttachStatusError(exec)
705		case apiclientgen.SandboxExecStatusFailed:
706			// The launch itself failed, so retrying would fail identically.
707			return true, execAttachStatusError(exec)
708		default:
709			return false, nil
710		}
711	}
712	
713	// sandboxStoppedAttachDone reports whether the sandbox itself has stopped (or is
714	// stopping or failed), which ends an attach: the terminal cannot outlive its
715	// sandbox, and reconnecting would loop against a runtime that is gone. A read
716	// that cannot establish this returns not-done, leaving the failure retriable.
717	func (a *App) sandboxStoppedAttachDone(ctx context.Context, projectID, sandboxID string) (bool, error) {
718		sandbox, ok := a.sandboxSnapshot(ctx, projectID, sandboxID)
719		if !ok {
720			return false, nil
721		}
722		switch sandbox.Runtime.RuntimeState.Or("") {
723		case sandboxRuntimeStateStopped, sandboxRuntimeStateStopping:
724			return true, fmt.Errorf("discobox %s is %s; detaching terminal", sandboxID, sandbox.Runtime.RuntimeState.Or(""))
725		}
726		if sandbox.Runtime.State == sandboxStateFailed {
727			return true, fmt.Errorf("discobox failed: %s", sandboxFailureReason(sandbox))
728		}
729		return false, nil
730	}
