732	// sandboxSnapshot fetches the sandbox once, returning ok=false when its state
733	// cannot be read. Callers that only act on a definitive state treat an
734	// unreadable sandbox as "unknown" rather than any particular phase.
735	func (a *App) sandboxSnapshot(ctx context.Context, projectID, sandboxID string) (*apimodel.Sandbox, bool) {
736		client, err := a.apiClient()
737		if err != nil {
738			return nil, false
739		}
740		res, err := client.GetSandbox(ctx, apiclientgen.GetSandboxParams{ProjectId: projectID, SandboxId: sandboxID})
741		if err != nil {
742			return nil, false
743		}
744		sandbox, err := expectResponse[apimodel.Sandbox](res)
745		if err != nil {
746			return nil, false
747		}
748		return sandbox, true
749	}
