751	func execAttachStatusError(exec *apimodel.SandboxExec) error {
752		if message := strings.TrimSpace(exec.Error.Or("")); message != "" {
753			return errors.New(message)
754		}
755		return fmt.Errorf("terminal is %s", exec.Status)
