758	const (
759		// The container being down is a runtime fact and a sandbox that could not
760		// be built is an existence one, so the two live on different fields
761		// (ADR 0034).
762		sandboxRuntimeStateStopped  = "stopped"
763		sandboxRuntimeStateStopping = "stopping"
764		sandboxStateFailed          = "failed"
765	)
