767	// attachPingInterval paces websocket keepalive pings on an exec attach. The
768	// pings keep an idle attach alive across NATs and proxies and detect a dead
769	// server, which an idle attach stream never would.
770	const attachPingInterval = 30 * time.Second
771	
772	// attachPingTimeout bounds how long a ping waits for the server's pong before
773	// the connection is considered dead.
774	const attachPingTimeout = 10 * time.Second
775	
776	// pingAttachWebSocket sends keepalive pings every attachPingInterval until ctx
777	// is canceled, returning an error when a ping goes unanswered for
778	// attachPingTimeout. Pongs are processed by the attach session's read loop.
779	func pingAttachWebSocket(ctx context.Context, conn *websocket.Conn) error {
780		return pingAttachWebSocketWithIntervals(ctx, conn, attachPingInterval, attachPingTimeout)
781	}
