37	// Reconcile loads the LATEST sandbox state and converges it. Semantics:
38	//   - missing sandbox: converged (settle).
39	//   - superseded mid-run (generation conflict): settle; the newer intent's
40	//     transactional mark re-runs us against current state.
41	//   - failure RECORDED on the resource (ErrorMessage set and the generation
42	//     converged): converged-to-failed — one logical attempt per intent. New
43	//     intent re-drives it.
44	//   - failure NOT recorded (crash/timeout before the failure write): return the
45	//     error so the row stays dirty and retries with backoff, which is what
46	//     makes it self-healing.
47	func (r *SandboxReconciler) Reconcile(ctx context.Context, id string) (reconcile.Result, error) {
48		projectID, sandboxID, err := splitSandboxDirtyID(id)
49		if err != nil {
50			return reconcile.Result{}, err
51		}
52		sandbox, err := r.store.GetSandbox(ctx, projectID, sandboxID)
53		if errors.Is(err, store.ErrNotFound) {
54			return reconcile.Result{}, nil
55		}
56		if err != nil {
57			return reconcile.Result{}, err
58		}
59	
60		result, err := r.ReconcileSandbox(ctx, sandbox)
61		if errors.Is(err, reconcile.ErrSuperseded) {
62			// Superseded: the newer intent's mark re-runs us, and it is the run that
63			// gets to arm a timer against the state it actually read.
64			return reconcile.Result{}, nil
65		}
66		if err == nil {
67			return result, nil
68		}
69		if current, gerr := r.store.GetSandbox(ctx, projectID, sandboxID); gerr == nil &&
70			current.ErrorMessage != nil && current.Converged() {
71			return reconcile.Result{}, nil // failure recorded on the resource: converged until new intent
72		}
73		return reconcile.Result{}, err
74	}
