211		switch sandbox.DesiredState {
212		case model.DesiredStatePresent:
213			return r.ensure(ctx, sandbox, generation)
214		case model.DesiredStateArchived:
215			return r.archive(ctx, sandbox, generation)
216		case model.DesiredStateDeleted:
217			return reconcile.Result{}, r.delete(ctx, sandbox, generation)
218		default:
219			return reconcile.Result{}, fmt.Errorf("unsupported sandbox desired state %q", sandbox.DesiredState)
220		}
221	}
