223	// ensure brings the sandbox's container into existence, built from the current
224	// spec. It does not start it.
225	//
226	// The one exception is a sandbox that has never run: creating a sandbox means
227	// asking for one, so the first create issues a start. A later ensure — a
228	// re-pin, a spec change, or a rebuild after the container was lost — creates
229	// the container and leaves its power state alone, which is what makes a
230	// recovered sandbox stay stopped until something uses it (ADR 0017 §13). Where
231	// that ensure replaces a *running* container, the pool agent restarts it into
232	// the new spec from its own observation; the start does not come from here
233	// (ADR 0021 §§3–4).
234	//
235	// The spec is taken as it stands. Nothing here advances the image pin: a
236	// sandbox runs what it is pinned to until an upgrade re-pins it (ADR 0021 §2).
237	func (r *SandboxReconciler) ensure(ctx context.Context, sandbox *model.Sandbox, generation int64) (reconcile.Result, error) {
238		// A settled failure is converged by design and needs new intent, not another
239		// attempt (ADR 0017 §4). Anything else gets the idempotent ensure below,
240		// because a dirty mark can come from an observation as well as from intent —
241		// "your container is gone" is the case that matters, and it arrives with the
242		// generations already in agreement.
243		if sandbox.Converged() && sandbox.ErrorMessage != nil {
244			return reconcile.Result{}, nil
245		}
246	
247		firstCreate := sandboxHasNeverRun(sandbox.State)
248		// A repair rides exactly this generation (ADR 0035): tear the runtime down
249		// first — container and disposable pool-host state dropped, durable tree
250		// kept — so the create below rebuilds from the retained tree instead of
251		// adopting whatever broken container or stale material survived. The
252		// teardown is the same provider Archive an archive uses, and it is
253		// idempotent, so a retry within this generation is safe; a later
254		// generation no longer matches and never tears down again.
255		//
256		// The teardown belongs to the repair that has not landed yet, which is why
257		// the generation alone does not select it. Ensure also runs on observation
258		// — "your container is gone" arrives with the generations already in
259		// agreement (above) — and on a settled repair generation that reads as a
260		// retry of a repair which already finished. Tearing down there re-archived
261		// a healthy sandbox on every attach, and left it settled as archived with
262		// its row still reading `ready`.
263		if sandbox.RepairGeneration == generation && !sandbox.Converged() && !firstCreate {
264			if err := r.archiveSandbox(ctx, sandbox); err != nil {
265				sandbox.ObservedGeneration = generation
266				sandbox.RecordFailure(model.SandboxStateFailed, err.Error(), failureReason(err))
267				if updateErr := r.update(ctx, sandbox, generation); updateErr != nil {
268					return reconcile.Result{}, updateErr
269				}
270				return reconcile.Result{}, err
271			}
272		}
273		if err := r.createSandbox(ctx, sandbox, firstCreate); err != nil {
274			sandbox.ObservedGeneration = generation
275			sandbox.RecordFailure(model.SandboxStateFailed, err.Error(), failureReason(err))
276			if updateErr := r.update(ctx, sandbox, generation); updateErr != nil {
277				return reconcile.Result{}, updateErr
278			}
279			return reconcile.Result{}, err
280		}
281	
282		// Parked waiting for the client's push. The generation is fully handled —
283		// there is nothing further to do until the client acts — so record it as
284		// observed and arm the give-up timer off StateChangedAt.
285		//
286		// The question is whether the push is still outstanding, not what state the
287		// sandbox is in: `awaiting_source` is where the resume starts from, and
288		// createSandbox above leaves it in place rather than clearing it, so keying
289		// on the state re-parked the sandbox it had just materialized the source
290		// into. It then sat at `awaiting_source` forever — running, with its source
291		// in place, and reported as still provisioning.
292		if awaitingSourcePush(sandbox) {
293			sandbox.ObservedGeneration = generation
294			if err := r.update(ctx, sandbox, generation); err != nil {
295				return reconcile.Result{}, err
296			}
297			return armSourceAwaitTimeout(sandbox), nil
298		}
299	
300		// The container exists and matches the spec, which is the whole of what this
301		// reconciler converges. `ready` says exactly that and nothing about power —
302		// whether the container is running is the pool agent's to report, and it
303		// already has: the create it just performed reported what it observed
304		// before returning (ADR 0034 §4), so an unarchive that rebuilt a stopped
305		// container reads `stopped` by the time this lands, without waiting for a
306		// complete sync.
307		sandbox.SetState(model.SandboxStateReady)
308		sandbox.ObservedGeneration = generation
309		sandbox.ClearFailure()
310		if err := r.update(ctx, sandbox, generation); err != nil {
311			return reconcile.Result{}, err
312		}
313		return reconcile.Result{}, nil
314	}
