316	// failureReason classifies a failed reconcile for the client that has to act on
317	// it. Only a failure a client can do something specific about gets a reason; the
318	// rest are recorded with the message alone.
319	func failureReason(err error) string {
320		if errors.Is(err, ErrImageUnavailable) {
321			return model.FailureReasonImageUnavailable
322		}
323		return ""
324	}
