332	func (r *SandboxReconciler) delete(ctx context.Context, sandbox *model.Sandbox, generation int64) error {
333		if sandbox.State == model.SandboxStateDeleted && sandbox.Converged() {
334			return r.softDelete(ctx, sandbox, generation)
335		}
336	
337		if err := r.deleteSandbox(ctx, sandbox); err != nil {
338			sandbox.ObservedGeneration = generation
339			sandbox.RecordFailure(model.SandboxStateFailed, err.Error(), failureReason(err))
340			if updateErr := r.update(ctx, sandbox, generation); updateErr != nil {
341				return updateErr
342			}
343			return err
344		}
345		sandbox.ObservedGeneration = generation
346		sandbox.SetState(model.SandboxStateDeleted)
347		sandbox.ClearFailure()
348		if err := r.update(ctx, sandbox, generation); err != nil {
349			return err
350		}
351		return r.softDelete(ctx, sandbox, generation)
352	}
