386	// createSandbox brings the sandbox's container into existence and parks it if
387	// its source has not arrived yet. It never starts anything: power is not this
388	// reconciler's business (ADR 0017 §9).
389	func (r *SandboxReconciler) createSandbox(ctx context.Context, sb *model.Sandbox, start bool) error {
390		provider, err := r.resolveProvider(ctx, sb)
391		if err != nil {
392			return err
393		}
394		if provider == nil {
395			now := time.Now().UTC()
396			sb.LastActiveAt = &now
397			return nil
398		}
399		secretState, err := r.store.OpenSandboxSecretState(ctx, sb)
400		if err != nil {
401			return err
402		}
403		secretState, err = r.ensureSandboxCreated(ctx, sb, provider, secretState, start)
404		if err != nil {
405			return err
406		}
407		if awaitingSourcePush(sb) {
408			if len(secretState) > 0 {
409				sb.SecretState = secretState
410			}
411			return parkForSourcePush(sb)
412		}
413		now := time.Now().UTC()
414		sb.LastActiveAt = &now
415		return nil
416	}
