418	func (r *SandboxReconciler) ensureSandboxCreated(ctx context.Context, sb *model.Sandbox, provider Provider, secretState []byte, start bool) ([]byte, error) {
419		ref := sandboxRefFromSandbox(sb)
420		// Repair the sandbox's secret bindings on the way up. The fan-out when a
421		// binding changes reaches the sandboxes that exist and are reachable at that
422		// moment; this catches what it missed — a sandbox archived across the change,
423		// a fan-out that stopped on an earlier sandbox's error — before the create
424		// options below read the assignments. It only covers a sandbox being
425		// reconciled: one whose generations already agree is never handed here, so
426		// drift on an idle sandbox waits for its next start.
427		if _, err := rebindSandboxSecretRows(ctx, r.store, sb.ProjectID, sb); err != nil {
428			return secretState, fmt.Errorf("rebind sandbox secrets: %w", err)
429		}
430		createOpts, err := r.createOptionsFromSandbox(ctx, sb)
431		if err != nil {
432			return secretState, err
433		}
434		createOpts.Start = start
435		if err := r.applyTrustKey(ctx, sb, &createOpts); err != nil {
436			return secretState, err
437		}
438		runtimeSandbox, state, err := provider.Create(ctx, ref, secretState, createOpts)
439		if err != nil && !errors.Is(err, ErrAlreadyExists) {
440			return secretState, err
441		}
442		if len(state) > 0 || secretState != nil {
443			sb.SecretState = state
444			secretState = state
445		}
446		if runtimeSandbox != nil {
447			setProviderState(sb, runtimeSandbox)
448		}
449		return secretState, nil
450	}
