452	func (r *SandboxReconciler) deleteSandbox(ctx context.Context, sb *model.Sandbox) error {
453		provider, err := r.resolveProvider(ctx, sb)
454		if err != nil {
455			return err
456		}
457		if provider == nil {
458			return nil
459		}
460		secretState, err := r.store.OpenSandboxSecretState(ctx, sb)
461		if err != nil {
462			return err
463		}
464		// Remove returns only once the provider has confirmed the container and the
465		// sandbox's data are both gone (ADR 0022 §3). Everything after this point —
466		// the deleted state, and then the row itself — is written on the strength of
467		// that confirmation, so an error here must not be swallowed. ErrNotFound is
468		// the one exception: a provider that never heard of the sandbox is not
469		// holding data for it.
470		state, err := provider.Remove(ctx, sandboxRefFromSandbox(sb), secretState)
471		if err != nil && !errors.Is(err, ErrNotFound) {
472			return err
473		}
474		sb.SecretState = state
475		if len(state) == 0 {
476			sb.ProviderState = nil
477		}
478		return nil
479	}
