579		opts.UserName = sb.UserName
580		opts.UserUID = sb.UserUID
581		opts.UserGID = sb.UserGID
582		opts.UserGroupName = sb.UserGroupName
583		opts.UserAdditionalGroups = append([]string(nil), sb.UserAdditionalGroups...)
584		opts.HomeDirectory = sb.HomeDirectory
585		opts.GitUserName = sb.GitUserName
586		opts.GitUserEmail = sb.GitUserEmail
