603					ConfigCommand:    cfg.ConfigCommand,
604					Files:            cfg.Files,
605					ConfiguredFiles:  cfg.ConfiguredFiles,
606					Secrets:          cfg.Secrets,
607					Env:              cfg.Env,
608					Volumes:          cfg.Volumes,
609					AdditionalGroups: cfg.AdditionalGroups,
