616	// sourceDataFingerprint makes the source-scoped mounts part of the runtime
617	// spec. Sandboxes created before source data existed therefore rebuild once
618	// instead of retaining a container that can never see the new mounts.
619	func sourceDataFingerprint(base, primary string, refs map[string]string) string {
620		if primary == "" && len(refs) == 0 {
621			return base
622		}
623		payload, err := json.Marshal(struct {
624			Version int               `json:"version"`
625			Base    string            `json:"base"`
626			Primary string            `json:"primary,omitempty"`
627			Refs    map[string]string `json:"refs,omitempty"`
628		}{Version: 1, Base: base, Primary: primary, Refs: refs})
629		if err != nil {
630			return "unfingerprintable-source-data"
631		}
632		sum := sha256.Sum256(payload)
633		return hex.EncodeToString(sum[:])
634	}
