		for _, scope := range scopes {
			switch scope {
			case poolagentauth.ScopeSandboxWrite, poolagentauth.ScopeExecRead, poolagentauth.ScopeExecWrite:
			default:
				return apperrors.NewStatusError(http.StatusForbidden, "a discobox may only push source into another, drive its terminals, or change its meta: "+scope)
			}
		}
		return nil
	}
	if !ok || principal.Type != auth.PrincipalTypeUser || principal.UserID == "" {
		return apperrors.NewStatusError(http.StatusForbidden, "user access required")
	}
	for _, scope := range scopes {
		if !principal.HasScope(scope) {
			return apperrors.NewStatusError(http.StatusForbidden, "user scope required: "+scope)
		}
	}
	return nil
}

