func (t requestHeaderTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	cloned := req.Clone(req.Context())
	if t.token != "" {
		cloned.Header.Set("Authorization", "Bearer "+t.token)
	}
	base := t.base
	if base == nil {
		base = http.DefaultTransport
	}
	return base.RoundTrip(cloned)
}

type textPlainErrorTransport struct {
	base http.RoundTripper
}

func (t textPlainErrorTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	base := t.base
	if base == nil {
		base = http.DefaultTransport
	}
	resp, err := base.RoundTrip(req)
	if err != nil || resp == nil || resp.StatusCode < 400 {
		return resp, err
	}
	ct, _, parseErr := mime.ParseMediaType(resp.Header.Get("Content-Type"))
	if parseErr != nil || ct != "text/plain" || resp.Body == nil {
		return resp, err
	}
	body, readErr := io.ReadAll(resp.Body)
	closeErr := resp.Body.Close()
	if readErr != nil {
		return resp, readErr
	}
	if closeErr != nil {
		return resp, closeErr
	}
	return nil, &plainStatusError{status: resp.Status, code: resp.StatusCode, body: strings.TrimSpace(string(body))}
}

// plainStatusError is a failed response whose body was plain text rather than
// the API's JSON: most often a route the server has never heard of, which a
// caller asking something newer than the server may treat as "not here".
type plainStatusError struct {
	status string
	code   int
	body   string
}

func (e *plainStatusError) Error() string {
	return fmt.Sprintf("request failed: %s: %s", e.status, e.body)
}

