// fakePoolManager implements sandbox.PoolManager over a single in-memory pool.
func newPoolAgentTestAuth(t *testing.T, projectID, poolID string, scopes ...string) (string, string) {
	t.Helper()
	publicKey, privateKey, err := ed25519.GenerateKey(nil)
	if err != nil {
		t.Fatalf("generate pool-agent test key: %v", err)
	}
	secretKey, err := paseto.NewV4AsymmetricSecretKeyFromEd25519(privateKey)
	if err != nil {
		t.Fatalf("load pool-agent test secret key: %v", err)
	}
	now := time.Now()
	token := paseto.NewToken()
	token.SetAudience(poolagentserver.PoolAgentAudience)
	token.SetIssuedAt(now)
	token.SetNotBefore(now.Add(-time.Minute))
	token.SetExpiration(now.Add(time.Hour))
	token.SetString("project_id", projectID)
	token.SetString("pool_id", poolID)
	if err := token.Set("scopes", scopes); err != nil {
		t.Fatalf("set pool-agent test scopes: %v", err)
	}
	return base64.StdEncoding.EncodeToString(publicKey), token.V4Sign(secretKey, nil)
}
type fakePoolManager struct {
	pool                    *model.Pool
	schedulable             bool
	mintedBootstrapTokens   int
	agentTokenClaims        []poolagentauth.TokenClaims
	sandboxAgentTokenClaims []poolagentauth.TokenClaims
	scheduledReconciles     int
	scheduledPoolID         string
	scheduledRepairs        []string
	scheduleUnblocks        bool

	mu       sync.Mutex
	progress []poolProgressReport
}

func (m *fakePoolManager) GetPool(context.Context, string, string) (*model.Pool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.pool == nil {
		return nil, apperrors.ErrNotFound
	}
	// A copy, because a caller reading fields off it races the test goroutine
	// that is standing in for a driver reporting progress.
	snapshot := *m.pool
